import hmac
import hashlib
import os
import time
import json
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import threading
import unicodedata

SERVER_SECRET = os.urandom(32)
SESSION_STORE = {}
USER_DB = {}
ADMIN_ACTIONS_LOG = []

def constant_time_compare(a: bytes, b: bytes) -> bool:
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= x ^ y
    return result == 0

def generate_session_token():
    return os.urandom(32).hex()

def compute_auth_signature(username: str, role: str, timestamp: int) -> str:
    msg = f"{username}:{role}:{timestamp}".encode('utf-8')
    return hmac.new(SERVER_SECRET, msg, hashlib.sha256).hexdigest()

def create_auth_cookie(username: str, role: str) -> str:
    ts = int(time.time())
    sig = compute_auth_signature(username, role, ts)
    payload = json.dumps({"user": username, "role": role, "ts": ts, "sig": sig})
    return payload

def verify_auth_cookie(cookie_data: str) -> dict:
    try:
        data = json.loads(cookie_data)
        username = data["user"]
        role = data["role"]
        ts = data["ts"]
        sig = data["sig"]

        if int(time.time()) - ts > 3600:
            return None

        expected_sig = compute_auth_signature(username, role, ts)
        if not constant_time_compare(sig.encode(), expected_sig.encode()):
            return None

        return {"user": username, "role": role}
    except (json.JSONDecodeError, KeyError, TypeError):
        return None

def normalize_username(username: str) -> str:
    """Single canonical normalization for all username operations.
    Uses NFKC + lowercase for consistent identity resolution."""
    return unicodedata.normalize('NFKC', username.lower())

def register_user(username: str, password: str, role: str = "user"):
    canonical = normalize_username(username)

    if canonical in USER_DB:
        return False, "User already exists"

    salt = os.urandom(16)
    pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)

    USER_DB[canonical] = {
        "display_name": canonical,
        "pw_hash": pw_hash,
        "salt": salt,
        "role": role
    }
    return True, "Registered"

def authenticate_user(username: str, password: str) -> str:
    canonical = normalize_username(username)

    if canonical not in USER_DB:
        return None

    user = USER_DB[canonical]
    pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), user["salt"], 100000)

    if not constant_time_compare(pw_hash, user["pw_hash"]):
        return None

    # Uses the canonical normalized username in the cookie
    cookie = create_auth_cookie(canonical, user["role"])
    return cookie

def check_admin_access(auth_data: dict) -> bool:
    """Check if the authenticated user has admin privileges.
    Looks up the user in the database to verify their role matches."""
    if auth_data is None:
        return False

    # Normalize the username from the cookie for lookup
    lookup_key = normalize_username(auth_data["user"])

    if lookup_key not in USER_DB:
        return False

    db_role = USER_DB[lookup_key]["role"]
    # Verify the role in the cookie matches the DB role
    return db_role == "admin" and auth_data["role"] == "admin"

def perform_admin_action(auth_data: dict, action: str, target_user: str) -> dict:
    """Perform an admin action with proper authorization."""

    # Re-verify admin status using normalized lookup
    lookup_key = normalize_username(auth_data["user"])
    if lookup_key not in USER_DB or USER_DB[lookup_key]["role"] != "admin":
        return {"error": "Forbidden"}

    if auth_data["role"] != "admin":
        return {"error": "Forbidden"}

    # Action: modify target user's role
    target_lookup = normalize_username(target_user)

    if action == "promote":
        if target_lookup in USER_DB:
            USER_DB[target_lookup]["role"] = "admin"
            ADMIN_ACTIONS_LOG.append({
                "actor": lookup_key,
                "action": "promote",
                "target": target_lookup,
                "time": int(time.time())
            })
            return {"success": True}
    elif action == "delete":
        if target_lookup in USER_DB:
            del USER_DB[target_lookup]
            ADMIN_ACTIONS_LOG.append({
                "actor": lookup_key,
                "action": "delete",
                "target": target_lookup,
                "time": int(time.time())
            })
            return {"success": True}

    return {"error": "Invalid action or target"}

class AuthHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 65536:
            self.send_response(413)
            self.end_headers()
            return
        body = self.rfile.read(content_length).decode('utf-8')

        path = urlparse(self.path).path

        if path == '/register':
            try:
                data = json.loads(body)
                username = str(data.get("username", ""))
                password = str(data.get("password", ""))
                if not username or not password or len(username) > 128 or len(password) > 256:
                    self.send_response(400)
                    self.end_headers()
                    self.wfile.write(b'{"error": "Invalid input"}')
                    return
                success, msg = register_user(username, password)
                self.send_response(200 if success else 400)
                self.end_headers()
                self.wfile.write(json.dumps({"message": msg}).encode())
            except (json.JSONDecodeError, TypeError):
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b'{"error": "Invalid JSON"}')

        elif path == '/login':
            try:
                data = json.loads(body)
                username = str(data.get("username", ""))
                password = str(data.get("password", ""))
                cookie = authenticate_user(username, password)
                if cookie:
                    self.send_response(200)
                    self.send_header('Set-Cookie', f'auth={cookie}; HttpOnly; Secure; SameSite=Strict; Path=/')
                    self.end_headers()
                    self.wfile.write(b'{"success": true}')
                else:
                    self.send_response(401)
                    self.end_headers()
                    self.wfile.write(b'{"error": "Invalid credentials"}')
            except (json.JSONDecodeError, TypeError):
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b'{"error": "Invalid JSON"}')

        elif path == '/admin/action':
            cookie_header = self.headers.get('Cookie', '')
            auth_cookie = None
            for part in cookie_header.split(';'):
                if part.strip().startswith('auth='):
                    auth_cookie = part.strip()[5:]
                    break

            auth_data = verify_auth_cookie(auth_cookie) if auth_cookie else None

            if not check_admin_access(auth_data):
                self.send_response(403)
                self.end_headers()
                self.wfile.write(b'{"error": "Forbidden"}')
                return

            try:
                data = json.loads(body)
                action = str(data.get("action", ""))
                target = str(data.get("target", ""))
                if action not in ("promote", "delete") or not target:
                    self.send_response(400)
                    self.end_headers()
                    self.wfile.write(b'{"error": "Invalid request"}')
                    return
                result = perform_admin_action(auth_data, action, target)
                self.send_response(200 if "success" in result else 403)
                self.end_headers()
                self.wfile.write(json.dumps(result).encode())
            except (json.JSONDecodeError, TypeError):
                self.send_response(400)
                self.end_headers()
                self.wfile.write(b'{"error": "Invalid JSON"}')
        else:
            self.send_response(404)
            self.end_headers()

def init_server():
    # Create initial admin user
    register_user("admin", "super_secret_password_123", role="admin")
    server = HTTPServer(('127.0.0.1', 8080), AuthHandler)
    return server

if __name__ == '__main__':
    server = init_server()
    print("Server running on port 8080")
    server.serve_forever()
